    els.btnSaveDocViewerContent?.addEventListener('click', async () => {
      const activeFile = STATE.localWorkspace.activeViewFile;
      if (!activeFile) return;
      const newContent = els.workspaceDocViewerEditor?.value || '';
      await createWorkspaceDocument(activeFile.path || activeFile.name, newContent, {
        author: 'user',
        note: 'Diedit manual oleh pengguna'
      });
      activeFile.content = newContent;
      if (els.workspaceDocViewerContent) els.workspaceDocViewerContent.textContent = newContent;
      setDocViewerEditMode(false);
      showToast(`✅ Perubahan pada "${activeFile.name}" berhasil disimpan!`);
      AudioEngine.success();
    });

    els.btnCopyDocViewerContent?.addEventListener('click', async () => {
      const isEditing = els.workspaceDocViewerEditor?.style.display !== 'none';
      const text = isEditing 
        ? (els.workspaceDocViewerEditor ? els.workspaceDocViewerEditor.value : '')
        : (els.workspaceDocViewerContent ? els.workspaceDocViewerContent.textContent : '');
      if (!text) return;
      if (typeof copyTextToClipboard === 'function') {
        copyTextToClipboard(text, null, '📋 Teks dokumen disalin ke clipboard!');
        AudioEngine.click();
      } else {
        try {
          await navigator.clipboard.writeText(text);
          showToast('📋 Teks dokumen disalin ke clipboard!');
          AudioEngine.click();
        } catch (_) {
          showToast('Gagal menyalin teks ke clipboard.', 'error');
        }
      }
    });

    els.btnDownloadDocViewerFile?.addEventListener('click', () => {
      if (!STATE.localWorkspace.activeViewFile) return;
      const fileObj = STATE.localWorkspace.activeViewFile;
      const isEditing = els.workspaceDocViewerEditor?.style.display !== 'none';
      const content = isEditing ? (els.workspaceDocViewerEditor?.value || '') : (fileObj.content || '');
      const blob = new Blob([content], { type: fileObj.type || 'text/plain;charset=utf-8' });
      downloadBlob(blob, fileObj.name || 'document.txt');
      showToast(`⬇️ Mengunduh "${fileObj.name}"...`);
      AudioEngine.click();
    });

    // Delegasi klik daftar file di explorer
    els.workspaceFileList?.addEventListener('click', (e) => {
      const viewBtn = e.target.closest('.btn-workspace-view-file');
      if (viewBtn) {
        const name = viewBtn.dataset.name;
        if (name) previewWorkspaceDocument(name, false);
        return;
      }
      const editBtn = e.target.closest('.btn-workspace-edit-file');
      if (editBtn) {
        const name = editBtn.dataset.name;
        if (name) previewWorkspaceDocument(name, true);
        return;
      }
      const dlBtn = e.target.closest('.btn-workspace-download-file');
      if (dlBtn) {
        const name = dlBtn.dataset.name;
        const fileObj = (STATE.localWorkspace.files || []).find(f => f.name === name);
        if (fileObj) {
          if (fileObj.content) {
            const blob = new Blob([fileObj.content], { type: fileObj.type || 'text/plain;charset=utf-8' });
            downloadBlob(blob, fileObj.name);
          } else if (fileObj.rawFile) {
            downloadBlob(fileObj.rawFile, fileObj.name);
          }
          showToast(`⬇️ Mengunduh "${name}"...`);
          AudioEngine.click();
        }
        return;
      }
      const delBtn = e.target.closest('.btn-workspace-delete-file');
      if (delBtn) {
        const name = delBtn.dataset.name;
        if (name) deleteWorkspaceDocument(name);
        return;
      }
      const snapBtn = e.target.closest('.btn-workspace-view-snapshots');
      if (snapBtn) {
        const name = snapBtn.dataset.name;
        if (name) {
          previewWorkspaceDocument(name);
          if (els.workspaceDocSnapshotsPanel) {
            els.workspaceDocSnapshotsPanel.style.display = 'block';
          }
        }
        return;
      }
    });

    // Toggle riwayat versi di viewer
    els.btnDocViewerSnapshotsToggle?.addEventListener('click', () => {
      if (!els.workspaceDocSnapshotsPanel) return;
      const isHidden = els.workspaceDocSnapshotsPanel.style.display === 'none';
      els.workspaceDocSnapshotsPanel.style.display = isHidden ? 'block' : 'none';
      AudioEngine.click();
    });

    // Delegasi aksi snapshot (preview / rollback)
    els.workspaceDocSnapshotsList?.addEventListener('click', async (e) => {
      const prevBtn = e.target.closest('.btn-preview-snapshot');
      if (prevBtn) {
        const fileName = prevBtn.dataset.name;
        const snapId = prevBtn.dataset.id;
        const list = (STATE.localWorkspace.snapshots && STATE.localWorkspace.snapshots[fileName]) || [];
        const snap = list.find(s => s.id === snapId);
        if (snap && els.workspaceDocViewerContent) {
          els.workspaceDocViewerContent.textContent = snap.content;
          showToast(`Pratinjau Versi ${snap.version} (${new Date(snap.timestamp).toLocaleTimeString()})`);
          AudioEngine.click();
        }
        return;
      }
      const rbBtn = e.target.closest('.btn-rollback-snapshot');
      if (rbBtn) {
        const fileName = rbBtn.dataset.name;
        const snapId = rbBtn.dataset.id;
        if (fileName && snapId) {
          await rollbackFileSnapshot(fileName, snapId);
        }
        return;
      }
    });

