    // Delegasi klik item di taskTrackerList
    els.taskTrackerList?.addEventListener('click', (e) => {
      const allowBtn = e.target.closest('.btn-approval-allow');
      if (allowBtn) {
        const taskId = allowBtn.dataset.taskId;
        const fileName = allowBtn.dataset.fileName;
        approveWorkspacePendingChange(fileName || taskId);
        return;
      }
      const rejectBtn = e.target.closest('.btn-approval-reject');
      if (rejectBtn) {
        const taskId = rejectBtn.dataset.taskId;
        const fileName = rejectBtn.dataset.fileName;
        rejectWorkspacePendingChange(fileName || taskId);
        return;
      }
      const statusBtn = e.target.closest('.task-status-btn');
      if (statusBtn) {
        const taskId = statusBtn.dataset.id;
        if (taskId) toggleTaskStatus(taskId);
        return;
      }
      const delBtn = e.target.closest('.task-delete-btn');
      if (delBtn) {
        const taskId = delBtn.dataset.id;
        if (taskId) deleteTask(taskId);
        return;
      }
    });

    // Global delegation for inline chat workspace actions
    document.addEventListener('click', (e) => {
      const inlineView = e.target.closest('.btn-inline-view-doc');
      if (inlineView) {
        const name = inlineView.dataset.name;
        if (name) previewWorkspaceDocument(name);
        return;
      }
      const inlineDl = e.target.closest('.btn-inline-download-doc');
      if (inlineDl) {
        const name = inlineDl.dataset.name;
        const fileObj = (STATE.localWorkspace.files || []).find(f => f.name === name);
        if (fileObj) {
          if (fileObj.content) {
            const blob = new Blob([fileObj.content], { type: fileObj.type || 'text/plain;charset=utf-8' });
            downloadBlob(blob, fileObj.name);
          } else if (fileObj.rawFile) {
            downloadBlob(fileObj.rawFile, fileObj.name);
          }
          showToast(`⬇️ Mengunduh "${name}"...`);
          AudioEngine.click();
        }
        return;
      }
    });

