    // Dismiss attachment, search, video search & image model dropdowns when clicking outside
    document.addEventListener('click', (e) => {
      // If clicking inside an active modal, cleanly close dropdowns without interfering with modal interaction
      if (e.target && e.target.closest && e.target.closest('.modal-backdrop.show')) {
        if (els.attachmentDropdown && els.attachmentDropdown.style.display !== 'none') {
          closeAttachmentDropdown();
        }
        if (els.imageModelDropdown && els.imageModelDropdown.style.display !== 'none') {
          closeImageModelDropdown();
        }
        if (els.musicModelDropdown && els.musicModelDropdown.style.display !== 'none') {
          closeMusicModelDropdown();
        }
        return;
      }

      if (els.attachmentDropdown && els.attachmentDropdown.style.display !== 'none') {
        if (!els.attachmentMenuWrapper?.contains(e.target)) {
          closeAttachmentDropdown();
        }
      }
      if (els.imageModelDropdown && els.imageModelDropdown.style.display !== 'none') {
        if (!els.topNavActiveToolWrap?.contains(e.target) && !els.photoEditReferenceCard?.contains(e.target) && !els.attachmentDropdown?.contains(e.target) && !els.imageModelMenuWrapper?.contains(e.target) && !els.imageGenActiveCard?.contains(e.target)) {
          closeImageModelDropdown();
        }
      }
      if (els.musicModelDropdown && els.musicModelDropdown.style.display !== 'none') {
        if (!els.topNavActiveToolWrap?.contains(e.target) && !els.attachmentDropdown?.contains(e.target) && !els.musicModelMenuWrapper?.contains(e.target) && !els.musicGenActiveCard?.contains(e.target)) {
          closeMusicModelDropdown();
        }
      }
      if (isSlashMenuOpen) {
        if (!els.slashCommandsMenu?.contains(e.target) && !els.promptInput?.contains(e.target)) {
          hideSlashCommandsMenu();
        }
      }
    });

    // Dismiss dropdowns & open modals on Escape key
    document.addEventListener('keydown', (e) => {
      if (e.key === 'Escape') {
        if (isSlashMenuOpen) {
          hideSlashCommandsMenu();
        }
        closeAttachmentDropdown();
        closeImageModelDropdown();
        closeMusicModelDropdown();
        els.modelDropdownMenu?.classList.remove('show');

        if (ImageLightbox.isOpen()) {
          return;
        }

        // Exit studio fullscreen on Escape if active
        const studioCard = els.aiFileStudioModal?.querySelector('.ai-file-studio-card');
        if (studioCard && studioCard.classList.contains('is-fullscreen')) {
          studioCard.classList.remove('is-fullscreen');
          if (els.btnToggleStudioFullscreen) {
            els.btnToggleStudioFullscreen.innerHTML = '<i class="fa-solid fa-expand"></i>';
            els.btnToggleStudioFullscreen.title = 'Layar Penuh (Full Screen)';
          }
          return;
        }

        // Close top-most active modal if open (kecuali #terminalModal agar tombol Esc di Vim/CLI/PowerShell tidak menutup jendela terminal)
        const openModals = Array.from(document.querySelectorAll('.modal-backdrop.show'));
        if (openModals.length > 0) {
          const topModal = openModals[openModals.length - 1];
          if (topModal.id !== 'terminalModal') {
            closeModal(topModal.id, true);
          }
        }
      }
    });


